import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';
import * as T from '../static/vendor/three-0.160.1.module.js';import Scene from '../static/pet-town-scene.js';import Town from '../static/pet-town-walk.js';
import {build,spec,inspectPanel} from '../static/pet-autumn-glass-panel-proof-20261028/panel.mjs';import {placeAndProbe} from '../static/pet-autumn-glass-panel-proof-20261028/placement.mjs';import {fitView} from '../static/pet-scalloped-path-proof-20261027/framing.mjs';
const near=(a,b,e=1e-6)=>assert.ok(Math.abs(a-b)<e,a+' != '+b),dir=path.resolve(import.meta.dirname,'../static/pet-autumn-glass-panel-proof-20261028');
function topology(g){const p=g.attributes.position,n=g.attributes.normal,ix=g.index,edges=new Map(),v=i=>new T.Vector3().fromBufferAttribute(p,i),key=i=>v(i).toArray().map(x=>Math.round(x*1e6)).join(':');let volume=0,degenerate=0,negative=0;for(let i=0;i<(ix?ix.count:p.count);i+=3){const ids=[0,1,2].map(k=>ix?ix.getX(i+k):i+k),[a,b,c]=ids.map(v),cross=b.clone().sub(a).cross(c.clone().sub(a));if(cross.lengthSq()<1e-20){degenerate++;continue;}volume+=a.dot(b.clone().cross(c))/6;const normal=ids.map(k=>new T.Vector3().fromBufferAttribute(n,k)).reduce((a,b)=>a.add(b),new T.Vector3()).normalize();if(cross.clone().normalize().dot(normal)<=0)negative++;const ks=ids.map(key);for(let j=0;j<3;j++){const a=ks[j],b=ks[(j+1)%3],k=[a,b].sort().join('|'),r=edges.get(k)||{count:0,direction:0};r.count++;r.direction+=a<b?1:-1;edges.set(k,r);}}return{volume,degenerate,negative,badEdges:[...edges.values()].filter(x=>x.count!==2||x.direction!==0).length};}
const fixture=(season='autumn')=>{const world=Town.createWorld(),model=Scene.buildWorld(T,world,{},null,null,season),item=build(T);return{world,model,item,dispose(){item.dispose();model.dispose();}};};
test('26 parts have real closed outward solid surfaces including glass, leaf, back and base',()=>{const a=build(T);assert.equal(a.parts.length,26);for(const {mesh,id}of a.parts){const t=topology(mesh.geometry);assert.deepEqual([t.badEdges,t.degenerate,t.negative],[0,0,0],id);assert.ok(t.volume>0,id);assert.ok(mesh.scale.toArray().every(x=>x>0));}assert.equal(a.inspect().invalidNormals,0);near(a.bounds.min[1],0);near(a.bounds.max[1],2.12);a.dispose();});
test('glass has a real leaf-shaped through-cutout occupied by the separate full-thickness amber inset',()=>{const a=build(T),r=inspectPanel(T,a);for(const k of['leafHole','leafHoleReverse']){assert.ok(r[k].includes(a.amber.name));assert.ok(!r[k].includes(a.glass.name));}for(const k of['clear','clearReverse']){assert.ok(r[k].includes(a.glass.name));assert.ok(!r[k].includes(a.amber.name));}const clear=new T.Box3().setFromObject(a.glass),leaf=new T.Box3().setFromObject(a.amber);near(clear.max.z-clear.min.z,.056);near(leaf.max.z-leaf.min.z,.056);near(clear.min.z,leaf.min.z);a.dispose();});
test('four lap joints occupy the removed front halves while the rear post halves remain continuous',()=>{const a=build(T),r=inspectPanel(T,a);assert.equal(r.lap.length,4);for(const row of r.lap){assert.equal(row.front.length,1);assert.match(row.front[0],/front-lap-rail/);assert.equal(row.rear.length,1);assert.match(row.rear[0],/post-rear-half/);}for(const sign of[-1,1]){const rear=a.posts.find(m=>m.name==='post-rear-half-'+sign),b=new T.Box3().setFromObject(rear);near(b.min.y,.12);near(b.max.y,2.12);for(const y of[.35,2.04]){const rail=a.rails.find(m=>Math.abs(m.position.y-y)<1e-6&&m.name.includes('front-lap')),r=new T.Box3().setFromObject(rail);near(r.min.z,b.max.z);assert.ok(r.max.x>=b.min.x&&r.min.x<=b.max.x);}}a.dispose();});
test('two stone soles are flat and each rear post actually embeds into its stone foot',()=>{const a=build(T);for(const f of a.feet){const b=new T.Box3().setFromObject(f),sign=Math.sign(f.position.x),post=a.posts.find(m=>m.name==='post-rear-half-'+sign),p=new T.Box3().setFromObject(post);near(b.min.y,0);assert.ok(b.intersectsBox(p));assert.ok(Math.min(b.max.y,p.max.y)-Math.max(b.min.y,p.min.y)>.039);}assert.equal(a.retainers.length,8);a.dispose();});
test('actual autumn and winter village floor supports keep ten soles and all world/collision state unchanged',()=>{for(const season of['autumn','winter']){const f=fixture(season),before=JSON.stringify(f.world),surfaces=f.model.surfaces.slice(),occluders=f.model.occluders.slice(),p=placeAndProbe(T,Scene,Town,f.world,f.model,f.item);assert.equal(p.supports.length,10);assert.ok(p.supports.every(x=>Math.abs(x.soleMinusFloor)<1e-6));assert.equal(p.finiteWalkability.samples,63);assert.equal(JSON.stringify(f.world),before);assert.deepEqual(f.model.surfaces,surfaces);assert.deepEqual(f.model.occluders,occluders);assert.deepEqual(f.item.group.scale.toArray(),[1,1,1]);assert.equal(p.normalPlacement,false);f.dispose();}});
test('every current road triangle, current full-card envelope and shore segment clears the complete footprint',()=>{const f=fixture(),p=placeAndProbe(T,Scene,Town,f.world,f.model,f.item);assert.equal(p.roads.reduce((n,r)=>n+r.triangles,0),2022);assert.ok(p.minimumRoadGap>1.62);assert.equal(p.originalSpriteEnvelopeClearance.checkedCards,38);assert.ok(p.originalSpriteEnvelopeClearance.minimumGap>1.0);assert.equal(p.shoreline.segments,7);assert.ok(p.shoreline.minimumGap>3.7);assert.ok(p.buildingProxyClearance.every(x=>!x.intersects));assert.equal(p.originalSpriteEnvelopeClearance.allCameraProjectionOcclusionGuaranteed,false);f.dispose();});
test('all40 actual meadow site envelopes clear the complete footprint, while initial native-overlapping anchor fails',()=>{const f=fixture(),p=placeAndProbe(T,Scene,Town,f.world,f.model,f.item);assert.equal(p.meadowEnvelopeClearance.sites,40);assert.equal(p.meadowEnvelopeClearance.clusterRadius,.52);assert.ok(p.meadowEnvelopeClearance.minimumGap>1.19);assert.throws(()=>placeAndProbe(T,Scene,Town,f.world,f.model,f.item,{x:1150,y:1350}),/meadow_cluster_overlap/);f.dispose();});
test('crowded and invalid placements fail without registering surfaces or changing the world',()=>{const f=fixture(),before=JSON.stringify(f.world);assert.throws(()=>placeAndProbe(T,Scene,Town,f.world,f.model,f.item,{x:NaN,y:1}),/anchor_invalid/);assert.throws(()=>placeAndProbe(T,Scene,Town,f.world,f.model,f.item,{x:f.world.width*.48,y:f.world.height*.52}),/clearance|blocked|overlap/);assert.throws(()=>placeAndProbe(T,Scene,Town,f.world,f.model,f.item,{x:9999,y:9999}),/floor_miss/);assert.equal(JSON.stringify(f.world),before);assert.equal(f.item.group.parent,null);f.dispose();});
test('finite portrait framing contains bounds under varied continuous-axis controls without object scaling',()=>{const a=build(T);for(const width of[300,370])for(let yaw=-180;yaw<=180;yaw+=30)for(const pitch of[-80,12,88]){const r=fitView(T,a.bounds,{yaw,pitch,roll:yaw/3,distance:1},width/350);assert.ok(Object.values(r.ndcBounds).every(v=>Number.isFinite(v)&&Math.abs(v)<.87));}assert.deepEqual(a.group.scale.toArray(),[1,1,1]);assert.equal(spec.bodyBinding,null);a.dispose();});
test('shared geometries/materials dispose exactly once with zero new lights/textures',()=>{const a=build(T),other=build(T);assert.deepEqual(a.budget,{meshes:26,geometries:5,materials:7,textures:0,lights:0,triangles:564});let count=0;for(const r of [...a.resources.geometries,...a.resources.materials])r.addEventListener('dispose',()=>count++);a.dispose();a.dispose();assert.equal(count,12);assert.equal(other.disposed,false);other.dispose();});
test('SHA pins and finite certificate agree; viewer keeps latest scene imports and writes no gameplay/storage',()=>{const sha=b=>crypto.createHash('sha256').update(b).digest('hex'),m=JSON.parse(fs.readFileSync(path.join(dir,'input-manifest.json'))),c=JSON.parse(fs.readFileSync(path.join(dir,'finite-geometry-certificate.json')));assert.equal(m.base_main_sha,'633010a49deac4ca6c9305d0266f74f0d0e568c0');for(const r of m.inputs){const b=fs.readFileSync(path.resolve(import.meta.dirname,'..',r.path));assert.equal(sha(b),r.sha256);assert.equal(b.length,r.bytes);}for(const r of m.files){const b=fs.readFileSync(path.join(dir,r.path));assert.equal(sha(b),r.sha256);}assert.equal(c.native_views_verified_by_this_certificate,false);assert.equal(c.bodyBinding,null);const v=fs.readFileSync(path.join(dir,'viewer.mjs'),'utf8');for(const n of['water-life','ocean-life','shore-transition','tree-variety','meadow-flowers','ground-finish','water-finish','environment'])assert.ok(v.includes('/static/pet-town-'+n+'.js'));assert.match(v,/toDataURL/);assert.match(v,/visibilitychange/);assert.doesNotMatch(v,/localStorage|sessionStorage|saveGame|registerAsset|setInterval|__capture/);});
